import type { DataMatrixSymbolInfo } from "./data-matrix-symbol-info.ts";

/**
 * Reed-Solomon error protection for Data Matrix ECC200, per ISO/IEC 16022 clause 5.3.
 *
 * <p>Codewords are elements of the field GF(2^8) generated by the primitive polynomial
 * {@code x^8 + x^4 + x^3 + x^2 + 1} (0x12D) with primitive element {@code alpha = 2}. For a block
 * that carries {@code n} error codewords the standard fixes the generator polynomial
 *
 * <pre>  g(x) = (x + alpha^1)(x + alpha^2) ... (x + alpha^n)</pre>
 *
 * whose roots are the first {@code n} consecutive powers of alpha. The generator is produced here
 * by multiplying its linear factors at run time; only the field polynomial is a compile-time
 * constant. A block's error codewords are the coefficients of the remainder of
 * {@code message(x) * x^n} divided by {@code g(x)}.
 *
 * <p>Symbols whose capacity exceeds one block hold several interleaved blocks, each protected on
 * its own; the resulting error codewords are then re-interleaved in the layout fixed by the symbol.
 *
 * Port of {@code org.bars4j.encode.matrix.datamatrix.DataMatrixErrorCorrection}.
 */

/** Primitive polynomial of the ECC200 field: {@code x^8 + x^4 + x^3 + x^2 + 1}. */
const FIELD_POLYNOMIAL = 0x12d;

/** Number of non-zero field elements, i.e. the multiplicative order of {@code alpha}. */
const FIELD_CYCLE = 255;

/** {@code alpha^power} for {@code power} in {@code [0, 2 * FIELD_CYCLE)}. */
const ALPHA_POWER = new Array<number>(FIELD_CYCLE * 2).fill(0);

/** Discrete logarithm to base {@code alpha}; defined for non-zero values {@code 1..255}. */
const ALPHA_LOG = new Array<number>(256).fill(0);

(() => {
  let element = 1;
  for (let exponent = 0; exponent < FIELD_CYCLE; exponent++) {
    ALPHA_POWER[exponent] = element;
    ALPHA_LOG[element] = exponent;
    element <<= 1;
    if (element >= 256) {
      element ^= FIELD_POLYNOMIAL;
    }
  }
  for (let exponent = FIELD_CYCLE; exponent < FIELD_CYCLE * 2; exponent++) {
    ALPHA_POWER[exponent] = ALPHA_POWER[exponent - FIELD_CYCLE];
  }
})();

/**
 * Appends the ECC200 error codewords to a symbol's data codewords, applying the interleaving
 * layout when the symbol spans several blocks.
 *
 * @param codewords  the data codewords, exactly {@link DataMatrixSymbolInfo.dataCapacity()} of them
 * @param symbolInfo the symbol whose protection applies
 * @return the data codewords followed by their error codewords
 */
export function encodeECC200(codewords: number[], symbolInfo: DataMatrixSymbolInfo): number[] {
  const dataCount = symbolInfo.dataCapacity();
  if (codewords.length !== dataCount) {
    throw new Error(`Expected ${dataCount} data codewords but received ${codewords.length}`);
  }
  const errorCount = symbolInfo.errorCodewords();
  const result = new Array<number>(dataCount + errorCount).fill(0);
  for (let i = 0; i < dataCount; i++) {
    result[i] = codewords[i];
  }

  const blocks = symbolInfo.interleavedBlockCount();
  if (blocks === 1) {
    const parity = blockParity(codewords, 0, dataCount, errorCount);
    for (let i = 0; i < errorCount; i++) {
      result[dataCount + i] = parity[i];
    }
    return result;
  }

  for (let block = 0; block < blocks; block++) {
    const blockDataCount = symbolInfo.dataLengthForInterleavedBlock(block + 1);
    const blockErrorCount = symbolInfo.errorLengthForInterleavedBlock(block + 1);

    const blockData = new Array<number>(blockDataCount).fill(0);
    for (let i = 0; i < blockDataCount; i++) {
      blockData[i] = codewords[block + i * blocks];
    }

    const parity = blockParity(blockData, 0, blockDataCount, blockErrorCount);
    for (let i = 0; i < blockErrorCount; i++) {
      result[dataCount + block + i * blocks] = parity[i];
    }
  }
  return result;
}

/**
 * Computes the error codewords of one block by reducing {@code message(x) * x^parityCount}
 * modulo the generator polynomial.
 */
function blockParity(
  message: number[],
  offset: number,
  length: number,
  parityCount: number,
): number[] {
  const generator = generatorPolynomial(parityCount);
  const accumulator = new Array<number>(length + parityCount).fill(0);
  for (let i = 0; i < length; i++) {
    accumulator[i] = message[offset + i];
  }

  for (let i = 0; i < length; i++) {
    const leadingTerm = accumulator[i];
    if (leadingTerm === 0) {
      continue;
    }
    for (let j = 0; j < generator.length; j++) {
      accumulator[i + j] ^= multiply(generator[j], leadingTerm);
    }
  }

  const parity = new Array<number>(parityCount).fill(0);
  for (let i = 0; i < parityCount; i++) {
    parity[i] = accumulator[length + i];
  }
  return parity;
}

/**
 * Builds the monic generator polynomial of the given degree, ordered from the highest power
 * downwards; the returned array has {@code degree + 1} entries.
 */
function generatorPolynomial(degree: number): number[] {
  let coefficients: number[] = [1];
  for (let root = 1; root <= degree; root++) {
    coefficients = multiplyByLinearFactor(coefficients, ALPHA_POWER[root]);
  }
  return coefficients;
}

/** Multiplies a polynomial (high power first) by the linear factor {@code (x + root)}. */
function multiplyByLinearFactor(polynomial: number[], root: number): number[] {
  const product = new Array<number>(polynomial.length + 1).fill(0);
  for (let i = 0; i < polynomial.length; i++) {
    const term = polynomial[i];
    product[i] ^= term;
    product[i + 1] ^= multiply(term, root);
  }
  return product;
}

/** Multiplies two field elements. */
function multiply(a: number, b: number): number {
  if (a === 0 || b === 0) {
    return 0;
  }
  return ALPHA_POWER[ALPHA_LOG[a] + ALPHA_LOG[b]];
}
